const A=document.getElementById("app"),nav=document.getElementById("nav"),title=document.getElementById("title");let map;
const icons={
 dashboard:`<svg viewBox="0 0 24 24"><path d="M3 12 12 3l9 9"/><path d="M5 10v10h14V10"/><path d="M9 20v-6h6v6"/></svg>`,
 trucks:`<svg viewBox="0 0 24 24"><path d="M3 6h11v11H3z"/><path d="M14 10h4l3 3v4h-7z"/><path d="M7 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4ZM18 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z"/></svg>`,
 drivers:`<svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="3"/><path d="M5 20a7 7 0 0 1 14 0"/></svg>`,
 routes:`<svg viewBox="0 0 24 24"><path d="M5 19c5 0 5-14 14-14"/><path d="m15 3 4 2-4 2"/><circle cx="5" cy="19" r="2"/></svg>`,
 trips:`<svg viewBox="0 0 24 24"><circle cx="6" cy="18" r="2"/><circle cx="18" cy="6" r="2"/><path d="M8 17c5-1 5-8 8-9"/></svg>`,
 loads:`<svg viewBox="0 0 24 24"><path d="M4 7h16v13H4z"/><path d="M8 7V5h8v2M8 11h8"/></svg>`,
 maintenance:`<svg viewBox="0 0 24 24"><path d="m14 6 4-3 3 3-3 4"/><path d="m13 7-9 9 4 4 9-9"/></svg>`,
 fuel:`<svg viewBox="0 0 24 24"><path d="M5 20V5h9v15M5 9h9M16 7h3l2 3v7a2 2 0 0 0 2 2"/><path d="M8 5V3h5v2"/></svg>`,
 documents:`<svg viewBox="0 0 24 24"><path d="M6 3h9l3 3v15H6z"/><path d="M15 3v4h4M9 12h6M9 16h6"/></svg>`,
 clients:`<svg viewBox="0 0 24 24"><path d="M4 21V6h16v15"/><path d="M8 6V3h8v3M8 10h2M14 10h2M8 14h2M14 14h2"/></svg>`,
 alerts:`<svg viewBox="0 0 24 24"><path d="M12 4 21 20H3z"/><path d="M12 9v5M12 17h.01"/></svg>`,
 reports:`<svg viewBox="0 0 24 24"><path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/></svg>`
};
const menus=[["dashboard",icons.dashboard,"Dashboard","OPERACIÓN"],["trucks",icons.trucks,"Camiones","FLOTA"],["drivers",icons.drivers,"Conductores","FLOTA"],["routes",icons.routes,"Rutas","OPERACIONES"],["trips",icons.trips,"Viajes","OPERACIONES"],["loads",icons.loads,"Cargas","OPERACIONES"],["clients",icons.clients,"Clientes","OPERACIONES"],["documents",icons.documents,"Documentos SII","FLOTA"],["maintenance",icons.maintenance,"Mantenciones","FLOTA"],["fuel",icons.fuel,"Combustible","FLOTA"],["alerts",icons.alerts,"Incidentes","FLOTA"],["reports",icons.reports,"Reportes","CONTROL"]];
function buildNav(){let groups=[];for(const m of menus){let g=groups.find(x=>x.name===m[3]);if(!g){g={name:m[3],items:[]};groups.push(g)}g.items.push(m)}nav.innerHTML=groups.map(g=>`<div class="nav-group"><div class="nav-section">${g.name}</div>${g.items.map(x=>`<button data-v="${x[0]}" title="${x[2]}"><i>${x[1]}</i><span>${x[2]}</span></button>`).join("")}</div>`).join("");nav.querySelectorAll("button").forEach(b=>b.onclick=()=>render(b.dataset.v))}buildNav();
const get=async u=>{const r=await fetch("/api/"+u);const d=await r.json();if(!r.ok)throw Error(d.error||"Error de servidor");return d};
const post=async(u,o)=>{const r=await fetch("/api/"+u,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(o)});const d=await r.json();if(!r.ok)throw Error(d.error||"No se pudo guardar");return d};
const patch=async(u,o)=>{const r=await fetch("/api/"+u,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(o)});const d=await r.json();if(!r.ok)throw Error(d.error||"No se pudo actualizar");return d};
const money=n=>new Intl.NumberFormat("es-CL",{style:"currency",currency:"CLP",maximumFractionDigits:0}).format(n||0);
const badge=s=>`<span class="badge ${/Pendiente|Borrador|Planificada|Mantención|Planificado/.test(s)?"amber":/atras|error|crítico|Cancelado/i.test(s)?"red":""}">${s||""}</span>`;
function render(v="dashboard"){nav.querySelectorAll("button").forEach(b=>b.classList.toggle("active",b.dataset.v===v));title.textContent=menus.find(x=>x[0]===v)?.[2]||"FleetChile";Promise.resolve(window[v]()).catch(e=>{A.innerHTML=`<div class="card"><h3>No se pudo cargar</h3><p>${e.message}</p></div>`})}
function k(l,v,f){return `<div class="card"><div class="label">${l}</div><div class="value">${v}</div><div class="good">● ${f}</div></div>`}
async function dashboard(){const[d,t,r,al]=await Promise.all([get("dashboard"),get("trucks"),get("routes"),get("alerts")]);let s={clients:0,active_trips:0};try{s=await get("core/summary")}catch(e){try{const[clients,trips]=await Promise.all([get("clients"),get("trips")]);s={clients:clients.length,active_trips:trips.filter(x=>!['Completado','Cancelado'].includes(x.status)).length}}catch(_){}}A.innerHTML=`<div class="grid kpis">${k("Camiones",d.trucks,"base operativa")}${k("En ruta",d.enroute,"GPS activo")}${k("Cargas",d.loads,"operacionales")}${k("Alertas",d.alerts,"sin resolver")}${k("Clientes",s.clients,"cartera activa")}${k("Viajes activos",s.active_trips,"operación")}</div><div class="grid two"><div class="card"><div style="display:flex;justify-content:space-between"><h3>Mapa operacional</h3><span class="live"><i></i> actualización automática</span></div><div id="map" class="map"></div></div><div class="card"><h3>Centro de alertas</h3>${al.filter(x=>!x.resolved).slice(0,5).map(x=>`<div class="alert"><b>${x.title}</b><br>${x.text}</div>`).join("")||"<p>Sin alertas pendientes.</p>"}<div class="hero"><b>Control GPS</b><p>Selecciona un camión para consultar su historial. Puedes simular una posición mientras integramos telemetría real.</p><button class="simulate" onclick="simulateGPS()">Simular GPS</button></div></div></div><div class="card" style="margin-top:15px"><h3>Rutas activas</h3>${table(["Camión","Origen","Destino","Avance","Estado"],r,x=>[x.truck,x.origin,x.destination,`${x.progress}%`,badge(x.status)])}</div>`;setTimeout(()=>makeMap(t),0)}
function makeMap(ts){if(map){map.remove();map=null}map=L.map("map").setView([-36.5,-72.5],6);L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:"© OpenStreetMap contributors"}).addTo(map);ts.filter(x=>x.lat&&x.lng).forEach(x=>{const m=L.marker([x.lat,x.lng]).addTo(map);m.bindPopup(`<b>${x.patente}</b><br>${x.driver||"Sin conductor"}<br>${x.status}<br>${x.location||""}<br><button onclick="openTruck(${x.id})">Ver ficha</button>`)})}
const gpsEscape=v=>String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
const gpsGet=async u=>{const r=await fetch("/api/"+u);const text=await r.text();let data=null;if(text){try{data=JSON.parse(text)}catch{throw Error(`Respuesta GPS inválida (${r.status})`)}}if(r.status===404)return null;if(!r.ok)throw Error(data?.error||`Error GPS ${r.status}`);return data};
function gpsSignal(value){if(!value)return {kind:"none",label:"Sin posición",detail:"No existen datos GPS"};const time=new Date(value).getTime();if(!Number.isFinite(time))return {kind:"error",label:"Dato inválido",detail:"Fecha GPS no válida"};const minutes=Math.max(0,Math.floor((Date.now()-time)/60000));if(minutes<=15)return {kind:"recent",label:"Señal reciente",detail:minutes<1?"Actualizada hace menos de un minuto":`Actualizada hace ${minutes} min`};return {kind:"old",label:"Señal antigua",detail:minutes<1440?`Actualizada hace ${minutes} min`:`Actualizada hace ${Math.floor(minutes/1440)} d`}}
function localInputValue(date){const offset=date.getTimezoneOffset()*60000;return new Date(date.getTime()-offset).toISOString().slice(0,16)}
async function openTruck(id){
 const t=await get("trucks"),x=t.find(a=>a.id==id);if(!x)return;
 if(window.truckTrackMap){window.truckTrackMap.remove();window.truckTrackMap=null}
 document.getElementById("drawerBody").innerHTML=`<div id="truckGpsStatus" class="gps-signal none">Cargando posición GPS…</div><h2>${gpsEscape(x.patente)}</h2><p>${gpsEscape(x.tipo)} · ${gpsEscape(x.capacidad_t)} t</p><div class="metric-grid"><div class="metric"><small>Estado</small><b>${gpsEscape(x.status)}</b></div><div class="metric"><small>Velocidad</small><b id="truckGpsSpeed">—</b></div><div class="metric"><small>Kilometraje</small><b id="truckGpsKm">${Number(x.km||0).toLocaleString("es-CL")} km</b></div><div class="metric"><small>Ubicación</small><b>${gpsEscape(x.location||"—")}</b></div><div class="metric"><small>Latitud</small><b id="truckGpsLat">—</b></div><div class="metric"><small>Longitud</small><b id="truckGpsLng">—</b></div><div class="metric"><small>Última posición</small><b id="truckGpsTime">—</b></div><div class="metric"><small>Antigüedad</small><b id="truckGpsAge">—</b></div></div><div class="gps-history-head"><div><h3>Historial GPS</h3><p class="muted">Consulta posiciones y recorrido en un período.</p></div></div><div class="gps-history-filters"><div class="field"><label>Desde</label><input id="gpsFrom" type="datetime-local"></div><div class="field"><label>Hasta</label><input id="gpsTo" type="datetime-local"></div><button class="primary" onclick="loadTruckGpsHistory(${id})">Consultar</button></div><div id="truckTrackMap" class="truck-track-map"></div><div id="truckGpsHistory" class="gps-history-state">Selecciona un período para consultar.</div>`;
 document.getElementById("drawer").classList.remove("hidden");
 const now=new Date(),from=new Date(now.getTime()-24*60*60*1000);document.getElementById("gpsFrom").value=localInputValue(from);document.getElementById("gpsTo").value=localInputValue(now);
 try{const position=await gpsGet(`fleet/trucks/${id}/position`);const status=document.getElementById("truckGpsStatus");if(!position){status.className="gps-signal none";status.textContent="Sin posición GPS registrada"}else{const signal=gpsSignal(position.recorded_at);status.className=`gps-signal ${signal.kind}`;status.textContent=`${signal.label} · ${signal.detail}`;document.getElementById("truckGpsSpeed").textContent=`${Number(position.speed_kmh||0).toLocaleString("es-CL")} km/h`;document.getElementById("truckGpsKm").textContent=`${Number(position.km||0).toLocaleString("es-CL")} km`;document.getElementById("truckGpsLat").textContent=Number(position.lat).toFixed(6);document.getElementById("truckGpsLng").textContent=Number(position.lng).toFixed(6);document.getElementById("truckGpsTime").textContent=formatDate(position.recorded_at);document.getElementById("truckGpsAge").textContent=signal.detail}}
 catch(e){const status=document.getElementById("truckGpsStatus");status.className="gps-signal error";status.textContent=`Error de posición: ${e.message}`}
 await loadTruckGpsHistory(id);
}
async function loadTruckGpsHistory(id){
 const container=document.getElementById("truckGpsHistory");if(!container)return;container.className="gps-history-state loading";container.textContent="Cargando historial GPS…";
 const fromValue=document.getElementById("gpsFrom")?.value,toValue=document.getElementById("gpsTo")?.value;
 if(!fromValue||!toValue){container.className="gps-history-state error";container.textContent="Debes indicar fecha inicial y final.";return}
 const from=new Date(fromValue),to=new Date(toValue);if(Number.isNaN(from.getTime())||Number.isNaN(to.getTime())||from>to){container.className="gps-history-state error";container.textContent="El período seleccionado no es válido.";return}
 const query=`from=${encodeURIComponent(from.toISOString())}&to=${encodeURIComponent(to.toISOString())}`;
 try{const [history,track]=await Promise.all([gpsGet(`fleet/trucks/${id}/positions?${query}`),gpsGet(`fleet/trucks/${id}/track?${query}`)]);const chronological=[...(history||[])].reverse();container.className="gps-history-state";container.innerHTML=chronological.length?`<div class="wrap"><table class="table"><thead><tr><th>Fecha/hora</th><th>Latitud</th><th>Longitud</th><th>Velocidad</th><th>Kilometraje</th><th>Viaje</th></tr></thead><tbody>${chronological.map(p=>`<tr><td>${gpsEscape(formatDate(p.recorded_at))}</td><td>${gpsEscape(p.lat)}</td><td>${gpsEscape(p.lng)}</td><td>${Number(p.speed_kmh||0).toLocaleString("es-CL")} km/h</td><td>${Number(p.km||0).toLocaleString("es-CL")} km</td><td>${p.trip_id?`#${gpsEscape(p.trip_id)}`:"—"}</td></tr>`).join("")}</tbody></table></div>`:"<div class=\"empty-state\">No existen posiciones en el período seleccionado.</div>";drawTruckTrack(track?.points||[])}catch(e){container.className="gps-history-state error";container.textContent=`No se pudo consultar el historial: ${e.message}`;drawTruckTrack([])}}
function drawTruckTrack(points){const el=document.getElementById("truckTrackMap");if(!el||typeof L==="undefined")return;if(window.truckTrackMap){window.truckTrackMap.remove();window.truckTrackMap=null}const valid=points.filter(p=>Number.isFinite(Number(p.lat))&&Number.isFinite(Number(p.lng))).map(p=>[Number(p.lat),Number(p.lng)]);const m=L.map(el).setView([-36.5,-72.5],6);L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:"© OpenStreetMap contributors"}).addTo(m);if(valid.length===1){L.marker(valid[0]).addTo(m);m.setView(valid[0],14)}else if(valid.length>1){L.polyline(valid,{color:"#0f67a9",weight:4,opacity:.85}).addTo(m);L.circleMarker(valid[0],{radius:6,color:"#218653"}).bindTooltip("Inicio").addTo(m);L.circleMarker(valid[valid.length-1],{radius:6,color:"#a52b2b"}).bindTooltip("Fin").addTo(m);m.fitBounds(valid,{padding:[24,24]})}else L.popup().setLatLng([-36.5,-72.5]).setContent("Sin recorrido para el período.").openOn(m);window.truckTrackMap=m}
async function simulateGPS(){const ts=await get("trucks"),t=ts.find(x=>x.status==="En ruta")||ts[0];if(!t)return;const lat=Number(t.lat||-36.6)+(Math.random()-.5)*.08,lng=Number(t.lng||-72.1)+(Math.random()-.5)*.08;await fetch(`/api/trucks/${t.id}/location`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({lat,lng,location:"GPS simulado",km:Number(t.km||0)+2,speed_kmh:Math.round(55+Math.random()*30),status:"En ruta"})});render("dashboard")}
function table(cols,rows,fn){return `<div class="wrap"><table class="table"><thead><tr>${cols.map(c=>`<th>${c}</th>`).join("")}</tr></thead><tbody>${rows.map(x=>`<tr>${fn(x).map(c=>`<td>${c??""}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`}
function listing(v,label,cols,rows,fn,newForm=v){A.innerHTML=`<div class="card"><div class="toolbar"><input class="search" id="q" placeholder="Buscar ${label.toLowerCase()}..."><button class="primary" onclick="openForm('${newForm}')">+ Nuevo</button></div><div id="tbl">${table(cols,rows,fn)}</div></div>`;document.getElementById("q").oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll("tbody tr").forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?"":"none")}}
const truck=x=>[x.patente,x.tipo,x.capacidad_t+" t",x.driver||"—",badge(x.status),x.location||"—",`<button class="secondary smallbtn" onclick="openTruckForm(${Number(x.id)})">Editar</button>`];
function formatDateOnly(v){if(!v)return "—";const m=String(v).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?`${m[3]}-${m[2]}-${m[1]}`:"—"}
const driver=x=>[x.name,x.rut||"—",x.license||"—",formatDateOnly(x.expiry),badge(x.status),`<button class="secondary smallbtn" onclick="openDriverForm(${Number(x.id)})">Editar</button>`];
const route=x=>[x.truck,x.origin,x.destination,(x.distance_km||0)+" km",(x.progress||0)+"%",badge(x.status)];
const load=x=>[x.client,x.guide,x.cargo,Number(x.weight_kg||0).toLocaleString("es-CL")+" kg",x.truck,`${x.origin} → ${x.destination}`,badge(x.status)];
const maint=x=>[x.truck,x.item,x.due,money(x.cost_clp),badge(x.status)];
const fuelRow=x=>[x.date,x.truck,x.liters+" L",money(x.price_clp),money(x.total_clp),x.station];
const fuelMetric=(value,suffix="")=>value===null||value===undefined?"—":`${Number(value).toLocaleString("es-CL",{maximumFractionDigits:2})}${suffix}`;
function trucks(){return get("trucks").then(r=>{window.currentTrucks=r;listing("trucks","camiones",["Patente","Tipo","Capacidad","Conductor","Estado","Ubicación",""],r,truck)})}
function drivers(){return get("drivers").then(r=>{window.currentDrivers=r;listing("drivers","conductores",["Nombre","RUT","Licencia","Vencimiento","Estado",""],r,driver)})}
function routes(){return get("routes").then(r=>listing("routes","rutas",["Camión","Origen","Destino","Distancia","Avance","Estado"],r,route))}
function loads(){return get("loads").then(r=>listing("loads","cargas",["Cliente","Guía","Carga","Peso","Camión","Ruta","Estado"],r,load))}
async function maintenance(filters={}){const params=new URLSearchParams({include_summary:"true"});for(const key of ["truck_id","from","to","status","maintenance_type"]){if(filters[key])params.set(key,filters[key])}if(filters.upcoming)params.set("upcoming","true");if(filters.overdue)params.set("overdue","true");try{const[data,trucks]=await Promise.all([get(`fleet/maintenance?${params}`),get("trucks")]);window.currentMaintenanceRecords=data.records||[];const totals=data.totals||{};A.innerHTML=`<div class="control-head"><div><div class="eyebrow">GESTIÓN DE FLOTA</div><h2>Mantenciones</h2><p>Planificación, ejecución y costos de mantenimiento por camión.</p></div><button class="primary" onclick="openMaintenanceForm()">+ Nueva mantención</button></div><div class="control-kpis"><div class="control-kpi"><span>Mantenciones</span><b>${Number(totals.maintenance_count||0).toLocaleString("es-CL")}</b><small>registros filtrados</small></div><div class="control-kpi"><span>Costo total</span><b>${money(totals.total_cost_clp)}</b><small>repuestos y mano de obra</small></div><div class="control-kpi"><span>Próximas</span><b>${Number(totals.upcoming_count||0).toLocaleString("es-CL")}</b><small>próximos 7 días</small></div><div class="control-kpi"><span>Vencidas</span><b>${Number(totals.overdue_count||0).toLocaleString("es-CL")}</b><small>por fecha u odómetro</small></div></div><div class="card" style="margin-top:15px"><div class="toolbar"><div class="formgrid" style="flex:1"><div class="field"><label>Camión</label><select id="maintenanceTruckFilter"><option value="">Todos</option>${trucks.map(t=>`<option value="${t.id}" ${String(filters.truck_id||"")===String(t.id)?"selected":""}>${gpsEscape(t.patente)}</option>`).join("")}</select></div><div class="field"><label>Desde</label><input id="maintenanceFrom" type="date" value="${gpsEscape(filters.from||"")}"></div><div class="field"><label>Hasta</label><input id="maintenanceTo" type="date" value="${gpsEscape(filters.to||"")}"></div><div class="field"><label>Estado</label><select id="maintenanceStatus"><option value="">Todos</option>${["Pendiente","En proceso","Completada","Cancelada"].map(v=>`<option ${filters.status===v?"selected":""}>${v}</option>`).join("")}</select></div><div class="field"><label>Tipo</label><select id="maintenanceType"><option value="">Todos</option>${["Preventiva","Correctiva"].map(v=>`<option ${filters.maintenance_type===v?"selected":""}>${v}</option>`).join("")}</select></div><label><input id="maintenanceUpcoming" type="checkbox" ${filters.upcoming?"checked":""}> Próximas</label><label><input id="maintenanceOverdue" type="checkbox" ${filters.overdue?"checked":""}> Vencidas</label><div class="formactions"><button type="button" class="secondary" onclick="applyMaintenanceFilters()">Aplicar</button></div></div></div><div class="wrap"><table class="table"><thead><tr><th>Fecha</th><th>Camión</th><th>Tipo</th><th>Servicio</th><th>Odómetro</th><th>Costo</th><th>Costo/km</th><th>Próxima</th><th>Estado</th><th></th></tr></thead><tbody>${(data.records||[]).map(x=>`<tr><td>${gpsEscape(String(x.performed_at||x.due||x.effective_date||"").slice(0,10)||"—")}</td><td>${gpsEscape(x.truck_patente||x.truck||"Sin resolver")}</td><td>${gpsEscape(x.maintenance_type||"Legacy")}</td><td>${gpsEscape(x.item||"—")}</td><td>${x.odometer_km===null||x.odometer_km===undefined?"—":`${Number(x.odometer_km).toLocaleString("es-CL")} km`}</td><td>${money(x.cost_clp)}</td><td>${x.cost_per_km===null?"—":money(x.cost_per_km)}</td><td>${gpsEscape(String(x.next_due_date||x.due||"").slice(0,10)||"—")}</td><td>${badge(x.status)}</td><td><button class="secondary smallbtn" onclick="openMaintenanceRecord(${Number(x.id)})">Editar</button></td></tr>`).join("")||'<tr><td colspan="10"><div class="empty-state">No hay mantenciones para los filtros seleccionados.</div></td></tr>'}</tbody></table></div></div><div class="card" style="margin-top:15px"><div class="section-head"><div><h3>Resumen por camión</h3><span class="muted">Los registros legacy sin camión resuelto se conservan fuera del resumen por camión.</span></div></div>${table(["Camión","Mantenciones","Costo","Próximas","Vencidas"],data.summary||[],x=>[gpsEscape(x.patente||`#${x.truck_id}`),x.maintenance_count,money(x.total_cost_clp),x.upcoming_count,x.overdue_count])}</div>`}catch(error){A.innerHTML=`<div class="card"><div class="empty-state">No se pudieron cargar las mantenciones: ${gpsEscape(error.message)}</div></div>`}}
function openMaintenanceRecord(id){const record=(window.currentMaintenanceRecords||[]).find(item=>Number(item.id)===Number(id));if(record)return openMaintenanceForm(record)}
function applyMaintenanceFilters(){return maintenance({truck_id:document.getElementById("maintenanceTruckFilter")?.value||"",from:document.getElementById("maintenanceFrom")?.value||"",to:document.getElementById("maintenanceTo")?.value||"",status:document.getElementById("maintenanceStatus")?.value||"",maintenance_type:document.getElementById("maintenanceType")?.value||"",upcoming:document.getElementById("maintenanceUpcoming")?.checked,overdue:document.getElementById("maintenanceOverdue")?.checked})}
async function openMaintenanceForm(record=null){const trucks=await get("trucks");const value=(key)=>gpsEscape(record?.[key]??"");document.getElementById("mt").textContent=record?"Editar mantención":"Nueva mantención";document.getElementById("form").innerHTML=`<div class="formgrid"><div class="field"><label>Camión</label><select name="truck_id" required><option value="">Seleccionar camión</option>${trucks.map(t=>`<option value="${t.id}" data-company="${t.company_id||""}" ${String(record?.truck_id||"")===String(t.id)?"selected":""}>${gpsEscape(t.patente)}</option>`).join("")}</select></div><div class="field"><label>Tipo</label><select name="maintenance_type" required>${["Preventiva","Correctiva"].map(v=>`<option ${record?.maintenance_type===v?"selected":""}>${v}</option>`).join("")}</select></div><div class="field"><label>Estado</label><select name="status">${["Pendiente","En proceso","Completada","Cancelada"].map(v=>`<option ${record?.status===v?"selected":""}>${v}</option>`).join("")}</select></div><div class="field"><label>Fecha programada</label><input name="due" type="date" value="${value("due")}"></div><div class="field"><label>Fecha efectiva</label><input name="performed_at" type="date" value="${value("performed_at")}"></div><div class="field"><label>Odómetro (km)</label><input name="odometer_km" type="number" min="0" step="0.1" value="${value("odometer_km")}"></div><div class="field"><label>Servicio / descripción</label><input name="item" value="${value("item")}" required></div><div class="field"><label>Taller</label><input name="workshop" value="${value("workshop")}"></div><div class="field"><label>Repuestos</label><input name="parts_description" value="${value("parts_description")}"></div><div class="field"><label>Costo repuestos</label><input name="parts_cost_clp" type="number" min="0" step="1" value="${value("parts_cost_clp")||0}"></div><div class="field"><label>Mano de obra</label><input name="labor_cost_clp" type="number" min="0" step="1" value="${value("labor_cost_clp")||0}"></div><div class="field"><label>Próxima fecha</label><input name="next_due_date" type="date" value="${value("next_due_date")}"></div><div class="field"><label>Próximo kilometraje</label><input name="next_due_odometer_km" type="number" min="0" step="0.1" value="${value("next_due_odometer_km")}"></div><div class="field"><label>Observaciones</label><input name="notes" value="${value("notes")}"></div><div class="formactions"><button class="primary">Guardar mantención</button></div></div>`;document.getElementById("modal").classList.remove("hidden");document.getElementById("form").onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));const selected=e.target.elements.truck_id.selectedOptions[0];data.truck_id=Number(data.truck_id);data.company_id=selected?.dataset.company?Number(selected.dataset.company):undefined;for(const key of ["odometer_km","parts_cost_clp","labor_cost_clp","next_due_odometer_km"]){data[key]=data[key]===""?null:Number(data[key])}if(record)await patch(`fleet/maintenance/${record.id}`,data);else await post("fleet/maintenance",data);close();await maintenance()}catch(error){alert(error.message)}}}
async function fuel(filters={}){const params=new URLSearchParams({include_summary:"true"});if(filters.truck_id)params.set("truck_id",filters.truck_id);if(filters.from)params.set("from",filters.from);if(filters.to)params.set("to",filters.to);const[data,trucks]=await Promise.all([get(`fleet/fuel?${params}`),get("trucks")]);const totals=data.totals||{};A.innerHTML=`<div class="control-head"><div><div class="eyebrow">GESTIÓN DE FLOTA</div><h2>Combustible</h2><p>Registro de cargas, costos y rendimiento por camión.</p></div><button class="primary" onclick="openFuelForm()">+ Registrar carga</button></div><div class="control-kpis"><div class="control-kpi"><span>Cargas</span><b>${Number(totals.loads_count||0).toLocaleString("es-CL")}</b><small>registros del período</small></div><div class="control-kpi"><span>Litros</span><b>${fuelMetric(totals.total_liters," L")}</b><small>volumen total</small></div><div class="control-kpi"><span>Costo</span><b>${money(totals.total_cost_clp)}</b><small>costo acumulado</small></div><div class="control-kpi"><span>Rendimiento</span><b>${fuelMetric(totals.efficiency_km_l," km/L")}</b><small>solo tramos calculables</small></div><div class="control-kpi"><span>Costo/km</span><b>${totals.cost_per_km===null||totals.cost_per_km===undefined?"—":money(totals.cost_per_km)}</b><small>solo tramos calculables</small></div></div><div class="card" style="margin-top:15px"><div class="toolbar"><div class="formgrid" style="flex:1"><div class="field"><label>Camión</label><select id="fuelTruckFilter"><option value="">Todos</option>${trucks.map(t=>`<option value="${t.id}" ${String(filters.truck_id||"")===String(t.id)?"selected":""}>${gpsEscape(t.patente)}</option>`).join("")}</select></div><div class="field"><label>Desde</label><input id="fuelFrom" type="date" value="${gpsEscape(filters.from||"")}"></div><div class="field"><label>Hasta</label><input id="fuelTo" type="date" value="${gpsEscape(filters.to||"")}"></div><div class="formactions"><button type="button" class="secondary" onclick="applyFuelFilters()">Aplicar filtros</button></div></div></div><div class="wrap"><table class="table"><thead><tr><th>Fecha</th><th>Camión</th><th>Litros</th><th>Precio/L</th><th>Total</th><th>Odómetro</th><th>Estación</th><th>Rendimiento</th><th>Costo/km</th></tr></thead><tbody>${(data.records||[]).map(x=>`<tr><td>${gpsEscape(String(x.date||"").slice(0,10))}</td><td>${gpsEscape(x.truck_patente||x.truck||"Sin resolver")}</td><td>${fuelMetric(x.liters," L")}</td><td>${money(x.price_clp)}</td><td>${money(x.total_clp)}</td><td>${fuelMetric(x.odometer_km," km")}</td><td>${gpsEscape(x.station||"—")}</td><td>${fuelMetric(x.efficiency_km_l," km/L")}</td><td>${x.cost_per_km===null?"—":money(x.cost_per_km)}</td></tr>`).join("")||'<tr><td colspan="9"><div class="empty-state">No hay cargas de combustible para el período.</div></td></tr>'}</tbody></table></div></div><div class="card" style="margin-top:15px"><div class="section-head"><div><h3>Resumen por camión</h3><span class="muted">Los indicadores se calculan solo con odómetros consecutivos válidos.</span></div></div>${table(["Camión","Cargas","Litros","Costo","Distancia calculable","Rendimiento","Costo/km"],data.summary||[],x=>[gpsEscape(x.patente||`#${x.truck_id}`),x.loads_count,fuelMetric(x.total_liters," L"),money(x.total_cost_clp),fuelMetric(x.calculable_distance_km," km"),fuelMetric(x.efficiency_km_l," km/L"),x.cost_per_km===null?"—":money(x.cost_per_km)])}</div>`}
function applyFuelFilters(){return fuel({truck_id:document.getElementById("fuelTruckFilter")?.value||"",from:document.getElementById("fuelFrom")?.value||"",to:document.getElementById("fuelTo")?.value||""})}
async function openFuelForm(){const trucks=await get("trucks");document.getElementById("mt").textContent="Registrar carga de combustible";document.getElementById("form").innerHTML=`<div class="formgrid"><div class="field"><label>Camión</label><select name="truck_id" required><option value="">Seleccionar camión</option>${trucks.map(t=>`<option value="${t.id}" data-company="${t.company_id||""}">${gpsEscape(t.patente)} · ${Number(t.km||0).toLocaleString("es-CL")} km</option>`).join("")}</select></div><div class="field"><label>Fecha</label><input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Litros</label><input name="liters" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Precio por litro</label><input name="price_clp" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Odómetro al cargar (km)</label><input name="odometer_km" type="number" min="0" step="0.1" required></div><div class="field"><label>Estación</label><input name="station"></div><div class="formactions"><button class="primary">Guardar carga</button></div></div>`;document.getElementById("modal").classList.remove("hidden");document.getElementById("form").onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));const selected=e.target.elements.truck_id.selectedOptions[0];data.truck_id=Number(data.truck_id);data.company_id=selected?.dataset.company?Number(selected.dataset.company):undefined;data.liters=Number(data.liters);data.price_clp=Number(data.price_clp);data.odometer_km=Number(data.odometer_km);await post("fleet/fuel",data);close();await fuel()}catch(err){alert(err.message)}}}
function companies(){return get("companies").then(r=>listing("companies","empresas",["Razón social","RUT","Nombre comercial","Región","Estado"],r,x=>[x.legal_name,x.rut||"—",x.trade_name||"—",x.region||"—",badge(x.active?"Activa":"Inactiva")],"companies"))}
function clients(){return get("clients").then(r=>listing("clients","clientes",["Nombre","RUT","Contacto","Email","Teléfono","Región"],r,x=>[x.name,x.rut||"—",x.contact_name||"—",x.email||"—",x.phone||"—",x.region||"—"],"clients"))}
function trips(){return get("trips").then(r=>listing("trips","viajes",["Viaje","Camión","Conductor","Cliente","Origen","Destino","Estado"],r,x=>[`<button class="secondary smallbtn" onclick="openTrip(${x.id})">${x.trip_number}</button>`,x.patente||"Sin asignar",x.driver_name||"Sin asignar",x.client_name||"—",x.origin,x.destination,badge(x.status)],"trips"))}
async function documents(filters={}){A.innerHTML='<div class="card"><div class="empty-state">Cargando documentos…</div></div>';const params=new URLSearchParams();for(const key of ["resource_type","truck_id","driver_id","document_type","status","from","to"]){if(filters[key])params.set(key,filters[key])}if(filters.situation==="upcoming")params.set("upcoming","true");if(filters.situation==="overdue")params.set("overdue","true");try{const[rows,options]=await Promise.all([get(`documents?${params}`),get("documents/options")]);window.currentDocumentRecords=rows;window.documentOptions=options;const resources=[...(options.trucks||[]).map(x=>({value:`vehicle:${x.id}`,label:`Camión · ${x.patente}`})),...(options.drivers||[]).map(x=>({value:`driver:${x.id}`,label:`Conductor · ${x.name}`}))];const selected=filters.truck_id?`vehicle:${filters.truck_id}`:filters.driver_id?`driver:${filters.driver_id}`:"";A.innerHTML=`<div class="control-head"><div><div class="eyebrow">GESTIÓN DE FLOTA</div><h2>Documentos SII</h2><p>Documentos y vencimientos de vehículos y conductores.</p></div><button class="primary" onclick="openDocumentForm()">+ Nuevo documento</button></div><div class="card"><div class="toolbar"><div class="formgrid" style="flex:1"><div class="field"><label>Recurso</label><select id="documentResource"><option value="">Todos</option>${resources.map(x=>`<option value="${x.value}" ${selected===x.value?"selected":""}>${gpsEscape(x.label)}</option>`).join("")}</select></div><div class="field"><label>Tipo</label><input id="documentType" value="${gpsEscape(filters.document_type||"")}"></div><div class="field"><label>Estado</label><input id="documentStatus" value="${gpsEscape(filters.status||"")}"></div><div class="field"><label>Situación</label><select id="documentSituation"><option value="" ${!filters.situation?"selected":""}>Todos</option><option value="upcoming" ${filters.situation==="upcoming"?"selected":""}>Próximos 30 días</option><option value="overdue" ${filters.situation==="overdue"?"selected":""}>Vencidos</option></select></div><div class="field"><label>Vence desde</label><input id="documentFrom" type="date" value="${gpsEscape(filters.from||"")}"></div><div class="field"><label>Vence hasta</label><input id="documentTo" type="date" value="${gpsEscape(filters.to||"")}"></div><div class="formactions"><button class="secondary" onclick="applyDocumentFilters()">Aplicar</button></div></div></div><div class="wrap"><table class="table"><thead><tr><th>Recurso</th><th>Tipo</th><th>Número</th><th>Emisión</th><th>Vencimiento</th><th>Estado</th><th>Situación</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><small>${x.resource_type==="vehicle"?"Vehículo":"Conductor"}</small><br><b>${gpsEscape(x.resource_name)}</b></td><td>${gpsEscape(x.document_type)}</td><td>${gpsEscape(x.document_number||"—")}</td><td>${gpsEscape(String(x.issued_at||"").slice(0,10)||"—")}</td><td>${gpsEscape(String(x.expires_at||"").slice(0,10)||"—")}</td><td>${badge(gpsEscape(x.status))}</td><td>${badge(gpsEscape(x.situation))}</td><td><button class="secondary smallbtn" onclick="openDocumentRecord('${x.resource_type}',${Number(x.id)})">Editar</button></td></tr>`).join("")||'<tr><td colspan="8"><div class="empty-state">No existen documentos para los filtros seleccionados.</div></td></tr>'}</tbody></table></div></div>`}catch(error){A.innerHTML=`<div class="card"><div class="empty-state">No se pudieron cargar los documentos: ${gpsEscape(error.message)}</div></div>`}}
function applyDocumentFilters(){const resource=document.getElementById("documentResource")?.value||"",filters={document_type:document.getElementById("documentType")?.value||"",status:document.getElementById("documentStatus")?.value||"",situation:document.getElementById("documentSituation")?.value||"",from:document.getElementById("documentFrom")?.value||"",to:document.getElementById("documentTo")?.value||""};if(resource){const[type,id]=resource.split(":");filters.resource_type=type;filters[type==="vehicle"?"truck_id":"driver_id"]=id}return documents(filters)}
function openDocumentRecord(type,id){const record=(window.currentDocumentRecords||[]).find(x=>x.resource_type===type&&Number(x.id)===Number(id));if(record)return openDocumentForm(record)}
async function openDocumentForm(record=null){const options=window.documentOptions||await get("documents/options"),resources=[...(options.trucks||[]).map(x=>({value:`vehicle:${x.id}`,label:`Camión · ${x.patente}`,company_id:x.company_id})),...(options.drivers||[]).map(x=>({value:`driver:${x.id}`,label:`Conductor · ${x.name}`,company_id:x.company_id}))],current=record?`${record.resource_type}:${record.resource_id}`:"";document.getElementById("mt").textContent=record?"Editar documento":"Nuevo documento";document.getElementById("form").innerHTML=`<div class="formgrid"><div class="field"><label>Vehículo o conductor</label><select name="resource" ${record?"disabled":""} required><option value="">Seleccionar recurso</option>${resources.map(x=>`<option value="${x.value}" data-company="${x.company_id||""}" ${current===x.value?"selected":""}>${gpsEscape(x.label)}</option>`).join("")}</select></div><div class="field"><label>Tipo</label><input name="document_type" value="${gpsEscape(record?.document_type||"")}" required></div><div class="field"><label>Número</label><input name="document_number" value="${gpsEscape(record?.document_number||"")}"></div><div class="field"><label>Fecha de emisión</label><input name="issued_at" type="date" value="${gpsEscape(String(record?.issued_at||"").slice(0,10))}"></div><div class="field"><label>Fecha de vencimiento</label><input name="expires_at" type="date" value="${gpsEscape(String(record?.expires_at||"").slice(0,10))}"></div><div class="field"><label>Estado</label><input name="status" value="${gpsEscape(record?.status||"Vigente")}" required></div><div class="field"><label>Archivo / referencia</label><input name="file_url" value="${gpsEscape(record?.file_url||"")}"></div><div class="field"><label>Observaciones</label><textarea name="notes">${gpsEscape(record?.notes||"")}</textarea></div><div class="formactions"><button class="primary" id="documentSave">Guardar documento</button></div></div>`;document.getElementById("modal").classList.remove("hidden");document.getElementById("form").onsubmit=async e=>{e.preventDefault();const save=document.getElementById("documentSave");save.disabled=true;save.textContent="Guardando…";try{const data=Object.fromEntries(new FormData(e.target));if(record){await patch(`${record.resource_type==='vehicle'?"vehicle":"driver"}-documents/${record.id}`,data)}else{const[type,id]=data.resource.split(":");delete data.resource;data[type==="vehicle"?"truck_id":"driver_id"]=Number(id);await post(`${type}-documents`,data)}close();await documents();alert("Documento guardado correctamente")}catch(error){save.disabled=false;save.textContent="Guardar documento";alert(error.message)}}}
async function alerts(filters={resolved:"false"}){const params=new URLSearchParams();for(const key of ["resolved","level","source_type","from","to"]){if(filters[key]!==undefined&&filters[key]!=="")params.set(key,filters[key])}try{const rows=await get(`fleet/alerts?${params}`);const canManage=Auth.user?.role_code==="admin"||(Auth.user?.permissions||[]).includes("fleet.manage");A.innerHTML=`<div class="control-head"><div><div class="eyebrow">GESTIÓN DE FLOTA</div><h2>Incidentes</h2><p>Alertas operacionales, mantenciones y vencimientos documentales.</p></div>${canManage?'<button class="primary" onclick="generateAlerts()">Actualizar alertas</button>':""}</div><div class="card"><div class="toolbar"><div class="formgrid" style="flex:1"><div class="field"><label>Estado</label><select id="alertResolved"><option value="false" ${filters.resolved==="false"?"selected":""}>Activas</option><option value="true" ${filters.resolved==="true"?"selected":""}>Resueltas</option><option value="" ${filters.resolved===""?"selected":""}>Todas</option></select></div><div class="field"><label>Severidad</label><select id="alertLevel"><option value="">Todas</option><option value="critical" ${filters.level==="critical"?"selected":""}>Crítica</option><option value="warning" ${filters.level==="warning"?"selected":""}>Advertencia</option></select></div><div class="field"><label>Origen</label><select id="alertSource"><option value="">Todos</option>${[["maintenance","Mantención"],["truck","Camión"],["vehicle_document","Documento vehículo"],["driver_document","Documento conductor"]].map(([v,l])=>`<option value="${v}" ${filters.source_type===v?"selected":""}>${l}</option>`).join("")}</select></div><div class="field"><label>Desde</label><input id="alertFrom" type="date" value="${gpsEscape(filters.from||"")}"></div><div class="field"><label>Hasta</label><input id="alertTo" type="date" value="${gpsEscape(filters.to||"")}"></div><div class="formactions"><button class="secondary" onclick="applyAlertFilters()">Aplicar</button></div></div></div>${rows.length?rows.map(x=>`<div class="alert"><div class="section-head"><div><b>${gpsEscape(x.title)}</b><div>${gpsEscape(x.text)}</div><small>${gpsEscape(alertSourceLabel(x))} · ${gpsEscape(formatDate(x.created_at))}</small></div><div>${badge(x.level==="critical"?"Crítico":"Advertencia")} ${badge(x.resolved?"Resuelta":"Activa")}</div></div>${canManage&&!x.resolved?`<button class="secondary smallbtn" onclick="resolveAlert(${Number(x.id)})">Marcar atendida</button>`:""}</div>`).join(""):'<div class="empty-state">No existen alertas para los filtros seleccionados.</div>'}</div>`}catch(error){A.innerHTML=`<div class="card"><div class="empty-state">No se pudieron cargar las alertas: ${gpsEscape(error.message)}</div></div>`}}
function alertSourceLabel(alert){if(alert.source_type==="maintenance")return `Mantención · ${alert.truck_patente||"Camión sin resolver"}`;if(alert.source_type==="truck")return `Camión · ${alert.truck_patente||`#${alert.source_id}`}`;if(alert.source_type==="vehicle_document")return `Documento vehículo · ${alert.truck_patente||"—"} · ${alert.document_type||""}`;if(alert.source_type==="driver_document")return `Documento conductor · ${alert.driver_name||"—"} · ${alert.document_type||""}`;return "Alerta legacy"}
function applyAlertFilters(){return alerts({resolved:document.getElementById("alertResolved")?.value??"false",level:document.getElementById("alertLevel")?.value||"",source_type:document.getElementById("alertSource")?.value||"",from:document.getElementById("alertFrom")?.value||"",to:document.getElementById("alertTo")?.value||""})}
async function generateAlerts(){try{const body={};if(Auth.user?.role_code==="admin"){const companyId=prompt("ID de la empresa para generar alertas:");if(!companyId)return;body.company_id=Number(companyId)}await post("fleet/alerts/generate",body);await alerts()}catch(error){alert(error.message)}}
async function resolveAlert(id){try{await post(`fleet/alerts/${id}/resolve`,{});await alerts()}catch(error){alert(error.message)}}
async function reports(){const[d,t,l,f,s]=await Promise.all([get("dashboard"),get("trucks"),get("loads"),get("fuel"),get("core/summary")]);A.innerHTML=`<div class="grid two"><div class="card"><h3>Indicadores operacionales</h3><p>Camiones: <b>${d.trucks}</b></p><p>En ruta: <b>${d.enroute}</b></p><p>Cargas: <b>${d.loads}</b></p><p>Alertas: <b>${d.alerts}</b></p><p>Combustible: <b>${money(d.fuel)}</b></p></div><div class="card"><h3>Plataforma</h3><p>Empresas: <b>${s.companies}</b></p><p>Usuarios: <b>${s.users}</b></p><p>Clientes: <b>${s.clients}</b></p><p>Viajes activos: <b>${s.active_trips}</b></p><p>Documentos por vencer: <b>${s.vehicle_documents_due+s.driver_documents_due}</b></p></div></div><div class="card" style="margin-top:15px"><h3>Utilización de flota</h3>${t.map(x=>`<p>${x.patente} — ${badge(x.status)} — ${Number(x.km||0).toLocaleString("es-CL")} km</p>`).join("")}</div>`}
const forms={trucks:[["patente","Patente"],["tipo","Tipo"],["capacidad_t","Capacidad (t)"],["driver","Conductor"],["location","Ubicación"]],routes:[["truck","Camión"],["origin","Origen"],["destination","Destino"],["distance_km","Distancia km"],["progress","Avance %"]],loads:[["client","Cliente"],["guide","Guía interna"],["cargo","Carga"],["weight_kg","Peso kg"],["volume_m3","Volumen m³"],["value_clp","Valor CLP"],["truck","Camión"],["origin","Origen"],["destination","Destino"]],fuel:[["date","Fecha"],["truck","Camión"],["liters","Litros"],["price_clp","Precio/L"],["station","Estación"]],companies:[["legal_name","Razón social"],["rut","RUT"],["trade_name","Nombre comercial"],["email","Email"],["phone","Teléfono"],["address","Dirección"],["commune","Comuna"],["region","Región"]],clients:[["name","Nombre"],["rut","RUT"],["contact_name","Contacto"],["email","Email"],["phone","Teléfono"],["address","Dirección"],["commune","Comuna"],["region","Región"]],trips:[["origin","Origen"],["destination","Destino"],["planned_departure","Salida planificada"],["planned_arrival","Llegada estimada"],["distance_km","Distancia km"],["revenue_clp","Ingreso CLP"],["notes","Observaciones"]]};
const endpoints={trucks:"trucks",routes:"routes",loads:"loads",fuel:"fuel",companies:"companies",clients:"clients",trips:"trips"};
async function openDriverForm(id=null){try{const record=id===null?null:(window.currentDrivers||[]).find(x=>Number(x.id)===Number(id));if(id!==null&&!record)return;const admin=Auth.user?.role_code==="admin",companies=admin&&!record?await get("companies"):[];document.getElementById("mt").textContent=record?"Editar Conductor":"Nuevo Conductor";document.getElementById("form").innerHTML=`<div class="formgrid">${admin?(record?`<input type="hidden" name="company_id" value="${Number(record.company_id)}">`:`<div class="field"><label>Empresa</label><select name="company_id" required><option value="">Seleccionar empresa</option>${companies.map(x=>`<option value="${x.id}">${gpsEscape(x.legal_name)}</option>`).join("")}</select></div>`):""}<div class="field"><label>Nombre</label><input name="name" value="${gpsEscape(record?.name||"")}" required></div><div class="field"><label>RUT</label><input name="rut" value="${gpsEscape(record?.rut||"")}"></div><div class="field"><label>Licencia</label><input name="license" value="${gpsEscape(record?.license||"")}"></div><div class="field"><label>Vencimiento</label><input name="expiry" type="date" value="${gpsEscape(String(record?.expiry||"").slice(0,10))}"></div><div class="field"><label>Estado</label><select name="status">${["Activo","Inactivo"].map(v=>`<option ${record?.status===v?"selected":""}>${v}</option>`).join("")}</select></div><div class="formactions"><button class="primary">Guardar</button></div></div>`;document.getElementById("modal").classList.remove("hidden");document.getElementById("form").onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));if(data.company_id)data.company_id=Number(data.company_id);if(record)await patch(`drivers/${record.id}`,data);else await post("drivers",data);close();render("drivers")}catch(err){alert(err.message)}}}catch(err){alert(err.message)}}
function openTruckForm(id){const record=(window.currentTrucks||[]).find(x=>Number(x.id)===Number(id));if(!record)return;document.getElementById("mt").textContent="Editar Camión";document.getElementById("form").innerHTML=`<div class="formgrid">${Auth.user?.role_code==="admin"?`<input type="hidden" name="company_id" value="${Number(record.company_id)}">`:""}<div class="field"><label>Patente</label><input name="patente" value="${gpsEscape(record.patente||"")}" required></div><div class="field"><label>Tipo</label><input name="tipo" value="${gpsEscape(record.tipo||"")}" required></div><div class="field"><label>Capacidad (t)</label><input name="capacidad_t" type="number" min="0" step="0.1" value="${gpsEscape(record.capacidad_t)}" required></div><div class="field"><label>Conductor</label><input name="driver" value="${gpsEscape(record.driver||"")}"></div><div class="field"><label>Estado</label><input name="status" value="${gpsEscape(record.status||"")}"></div><div class="field"><label>Ubicación</label><input name="location" value="${gpsEscape(record.location||"")}"></div><div class="formactions"><button class="primary">Guardar</button></div></div>`;document.getElementById("modal").classList.remove("hidden");document.getElementById("form").onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));data.capacidad_t=Number(data.capacidad_t);if(data.company_id)data.company_id=Number(data.company_id);await patch(`trucks/${record.id}`,data);close();render("trucks")}catch(err){alert(err.message)}}}
function openForm(v){if(v==="drivers")return openDriverForm();const f=forms[v];if(!f)return;document.getElementById("mt").textContent="Nuevo "+(menus.find(x=>x[0]===v)?.[2]||v);document.getElementById("form").innerHTML=`<div class="formgrid">${f.map(([k,l])=>`<div class="field"><label>${l}</label><input name="${k}" ${k.includes("date")||k.includes("departure")||k.includes("arrival")?"type=datetime-local":""} required></div>`).join("")}<div class="formactions"><button class="primary">Guardar</button></div></div>`;document.getElementById("modal").classList.remove("hidden");document.getElementById("form").onsubmit=async e=>{e.preventDefault();try{let o=Object.fromEntries(new FormData(e.target));["capacidad_t","distance_km","progress","weight_kg","volume_m3","value_clp","liters","price_clp","revenue_clp"].forEach(k=>{if(o[k]!==undefined)o[k]=Number(o[k])});await post(endpoints[v],o);close();render(v)}catch(err){alert(err.message)}}}
function close(){document.getElementById("modal").classList.add("hidden")}
async function openTrip(id){const t=await get(`operations/trips/${id}`);const o=await get("operations/options");const truck=t.patente?`<b>${t.patente}</b>`:`<span>Sin asignar</span>`;const driver=t.driver_name?`<b>${t.driver_name}</b>`:`<span>Sin asignar</span>`;const client=t.client_name||"Sin cliente";const loads=t.loads||[];const events=t.events||[];const checks=t.checklists||[];const proofs=t.proofs||[];const statuses=["Planificado","Asignado","En carga","En tránsito","Detenido","Llegó a destino","Descargando","Completado","Cancelado"];document.getElementById("drawerBody").innerHTML=`<div class="trip-detail-head"><div><small>VIAJE</small><h2>${t.trip_number}</h2><div>${badge(t.status)} · ${client}</div></div><button class="secondary smallbtn" onclick="closeTrip()">Cerrar</button></div><div class="trip-kpis"><div><small>Camión</small><b>${truck}</b></div><div><small>Conductor</small><b>${driver}</b></div><div><small>Origen</small><b>${t.origin||"—"}</b></div><div><small>Destino</small><b>${t.destination||"—"}</b></div></div><div class="trip-actions"><select id="tripStatus">${statuses.map(s=>`<option value="${s}" ${s===t.status?"selected":""}>${s}</option>`).join("")}</select><button class="primary" onclick="changeTripStatus(${id})">Actualizar estado</button><button class="secondary" onclick="assignTrip(${id})">Asignar recursos</button></div><div class="trip-tabs"><button class="active" onclick="tripTab('overview',${id})">Resumen</button><button onclick="tripTab('assign',${id})">Asignación</button><button onclick="tripTab('loads',${id})">Cargas</button><button onclick="tripTab('checklist',${id})">Checklist</button><button onclick="tripTab('events',${id})">Eventos</button><button onclick="tripTab('delivery',${id})">Entrega / POD</button></div><div id="tripPanel" class="trip-panel"><div class="detail-grid"><p><small>Distancia</small><b>${Number(t.distance_km||t.route_distance||0).toLocaleString("es-CL")} km</b></p><p><small>Salida planificada</small><b>${formatDate(t.planned_departure)}</b></p><p><small>Llegada estimada</small><b>${formatDate(t.planned_arrival)}</b></p><p><small>Salida real</small><b>${formatDate(t.actual_departure)}</b></p></div><h3>Cargas asociadas</h3>${loads.length?loads.map(x=>`<div class="operation-row"><div><b>${x.cargo}</b><small>${x.guide||"Sin guía"} · ${Number(x.weight_kg||0).toLocaleString("es-CL")} kg</small></div>${badge(x.status)}</div>`).join(""):"<p>No hay cargas asociadas.</p>"}</div>`;document.getElementById("drawer").classList.remove("hidden");window.currentTrip=t;window.operationOptions=o}
function formatDate(v){return v?new Date(v).toLocaleString("es-CL"):"—"}
function closeTrip(){document.getElementById("drawer").classList.add("hidden")}
async function changeTripStatus(id){try{const s=document.getElementById("tripStatus").value;await patch(`operations/trips/${id}/status`,{status:s});await openTrip(id)}catch(e){alert(e.message)}}
async function assignTrip(id){const o=window.operationOptions||await get("operations/options");const t=window.currentTrip;document.getElementById("tripPanel").innerHTML=`<h3>Asignar recursos operacionales</h3><div class="assignment-grid"><button class="assignment-card" onclick="chooseAssignment('truck',${id})"><small>CAMIÓN ACTUAL</small><strong>${t?.patente||"Sin asignar"}</strong><span>Seleccionar camión</span></button><button class="assignment-card" onclick="chooseAssignment('driver',${id})"><small>CONDUCTOR ACTUAL</small><strong>${t?.driver_name||"Sin asignar"}</strong><span>Seleccionar conductor</span></button><button class="assignment-card" onclick="chooseAssignment('client',${id})"><small>CLIENTE</small><strong>${t?.client_name||"Sin cliente"}</strong><span>Seleccionar cliente</span></button><button class="assignment-card" onclick="chooseAssignment('route',${id})"><small>RUTA</small><strong>${t?.route_origin&&t?.route_destination?t.route_origin+" → "+t.route_destination:"Sin ruta"}</strong><span>Seleccionar ruta</span></button></div>`;window.operationOptions=o}
async function chooseAssignment(type,id){const o=window.operationOptions||await get("operations/options");const labels={truck:"camión",driver:"conductor",client:"cliente",route:"ruta"};const arr=o[type+"s"]||[];document.getElementById("tripPanel").innerHTML=`<h3>Seleccionar ${labels[type]}</h3>${arr.map(x=>{const name=type==='truck'?x.patente:type==='driver'?x.name:type==='client'?x.name:`${x.origin} → ${x.destination}`;const sub=type==='truck'?[x.tipo,x.status].filter(Boolean).join(" · "):type==='driver'?[x.rut,x.status].filter(Boolean).join(" · "):type==='client'?[x.rut,x.contact_name].filter(Boolean).join(" · "):((x.distance_km||0)+" km");return `<button class="assignment-card" onclick="applyAssignment('${type}',${id},${x.id})"><strong>${name}</strong><span>${sub}</span></button>`}).join("")||"<p>No hay opciones disponibles.</p>"}`}
async function applyAssignment(type,id,value){try{const o=window.operationOptions||await get("operations/options");const t=window.currentTrip||await get(`operations/trips/${id}`);const payload={truck_id:t.truck_id,driver_id:t.driver_id,client_id:t.client_id,route_id:t.route_id,origin:t.origin,destination:t.destination,distance_km:t.distance_km};payload[type+"_id"]=value;if(type==='route'){const r=o.routes.find(x=>x.id==value);if(r){payload.origin=r.origin;payload.destination=r.destination;payload.distance_km=r.distance_km}}if(!payload.truck_id||!payload.driver_id)throw Error("El viaje requiere camión y conductor para completar la asignación.");await patch(`operations/trips/${id}/assign`,payload);await openTrip(id)}catch(e){alert(e.message)}}
async function tripTab(tab,id){const t=window.currentTrip&&window.currentTrip.id==id?window.currentTrip:await get(`operations/trips/${id}`);window.currentTrip=t;if(tab==='assign')return assignTrip(id);if(tab==='loads'){document.getElementById("tripPanel").innerHTML=`<h3>Cargas del viaje</h3>${(t.loads||[]).map(x=>`<div class="operation-row"><div><b>${x.cargo}</b><small>${x.guide||"Sin guía"} · ${Number(x.weight_kg||0).toLocaleString("es-CL")} kg · ${x.origin||"—"} → ${x.destination||"—"}</small></div>${badge(x.status)}</div>`).join("")||"<p>No hay cargas asociadas.</p>"}<button class="primary smallbtn" onclick="addTripLoad(${id})">+ Agregar carga</button>`;return}if(tab==='checklist'){document.getElementById("tripPanel").innerHTML=`<h3>Checklist preoperacional</h3>${(t.checklists||[]).map(x=>`<div class="operation-row"><div><b>${x.checklist_type}</b><small>${formatDate(x.completed_at)} · ${x.observations||"Sin observaciones"}</small></div>${badge(x.status)}</div>`).join("")||"<p>No hay checklist registrado.</p>"}<button class="primary smallbtn" onclick="addChecklist(${id})">+ Registrar checklist</button>`;return}if(tab==='events'){document.getElementById("tripPanel").innerHTML=`<h3>Línea de tiempo</h3>${(t.events||[]).map(x=>`<div class="timeline-item"><span></span><div><b>${x.event_type}</b><small>${formatDate(x.event_time)}</small><p>${x.notes||""}</p></div></div>`).join("")||"<p>No hay eventos registrados.</p>"}<button class="primary smallbtn" onclick="addTripEvent(${id})">+ Registrar evento</button>`;return}if(tab==='delivery'){document.getElementById("tripPanel").innerHTML=`<h3>Entrega / POD</h3>${(t.proofs||[]).map(x=>`<div class="operation-row"><div><b>${x.recipient_name||"Receptor no indicado"}</b><small>${formatDate(x.delivered_at)} · ${x.notes||""}</small></div><span>${x.photo_url?"Foto ✓":""} ${x.signature_url?"Firma ✓":""}</span></div>`).join("")||"<p>No hay entregas registradas.</p>"}<button class="primary smallbtn" onclick="registerDelivery(${id})">+ Registrar entrega</button>`;return}document.getElementById("tripPanel").innerHTML=`<div class="detail-grid"><p><small>Distancia</small><b>${Number(t.distance_km||t.route_distance||0).toLocaleString("es-CL")} km</b></p><p><small>Salida planificada</small><b>${formatDate(t.planned_departure)}</b></p><p><small>Llegada estimada</small><b>${formatDate(t.planned_arrival)}</b></p><p><small>Salida real</small><b>${formatDate(t.actual_departure)}</b></p></div>`}
async function addTripLoad(id){const cargo=prompt("Carga:");if(!cargo)return;const guide=prompt("Guía interna (opcional):")||"";const weight=Number(prompt("Peso kg:")||0);try{await post(`operations/trips/${id}/loads`,{cargo,guide,weight_kg:weight,status:"Planificada"});await openTrip(id);await tripTab("loads",id)}catch(e){alert(e.message)}}
async function addChecklist(id){const status=confirm("¿Checklist aprobado?\nAceptar = Aprobado / Cancelar = Pendiente")?"Aprobado":"Pendiente";const t=window.currentTrip;if(!t?.truck_id){alert("Primero asigna un camión al viaje.");return}try{await post(`operations/trips/${id}/checklist`,{truck_id:t.truck_id,driver_id:t.driver_id,status,items:[],observations:prompt("Observaciones (opcional):")||""});await openTrip(id);await tripTab("checklist",id)}catch(e){alert(e.message)}}
async function addTripEvent(id){const event_type=prompt("Tipo de evento:");if(!event_type)return;try{await post(`operations/trips/${id}/events`,{event_type,notes:prompt("Notas:")||""});await openTrip(id);await tripTab("events",id)}catch(e){alert(e.message)}}
async function registerDelivery(id){const t=window.currentTrip;if(!t?.loads?.length){alert("El viaje no tiene cargas asociadas.");return}const load=t.loads[0];const recipient_name=prompt("Nombre del receptor:")||"";if(!recipient_name)return;const recipient_rut=prompt("RUT del receptor (opcional):")||"";const notes=prompt("Observaciones:")||"";try{await post(`operations/trips/${id}/deliver`,{load_id:load.id,recipient_name,recipient_rut,notes});await openTrip(id);await tripTab("delivery",id)}catch(e){alert(e.message)}}

dashboard=async function(){try{const data=await get("economics/kpis"),o=data.operations||{},e=data.economics||{},f=data.fleet||{},m=data.maintenance||{},d=data.documents||{},a=data.alerts||{},c=data.checklist||{},fmt=(v,fn=v=>Number(v).toLocaleString("es-CL"))=>v===null||v===undefined?"N/D":fn(v);A.innerHTML=`<div class="control-head"><div><div class="eyebrow">CONTROL ECONÓMICO Y OPERACIONAL</div><h2>Dashboard ejecutivo</h2><p>Indicadores calculados bajo demanda. Delta/km utiliza distancia oficial planificada.</p></div></div><div class="grid kpis">${k("Viajes completados",fmt(o.completed),"operación")}${k("Cumplimiento",fmt(o.compliance?.percentage,v=>`${Number(v).toLocaleString("es-CL",{maximumFractionDigits:1})}%`),`${o.compliance?.completed||0}/${o.compliance?.denominator??"N/D"} planificados`)}${k("Cargas",fmt(o.loads?.registered),`${o.loads?.delivered??"N/D"} entregadas`)}${k("Ingreso reconocido",fmt(e.recognized_revenue?.amount,money),`${e.recognized_revenue?.trips??0} viajes`)}${k("Costos directos",fmt(e.recognized_costs?.amount,money),`${e.recognized_costs?.trips??0} viajes`)}${k("Delta provisional",fmt(e.delta?.provisional,money),"no definitivo")}${k("Delta reconciliado",fmt(e.delta?.reconciled,money),"conciliado")}${k("Delta/km",fmt(e.delta_per_km?.provisional,money),"distancia oficial planificada")}</div><div class="grid kpis" style="margin-top:15px">${k("Missing data",fmt(e.delta?.missing_data_trips),"viajes")}${k("Camiones activos",fmt(f.active),"flota")}${k("En mantenimiento",fmt(f.maintenance),"camiones")}${k("Conductores activos",fmt(f.drivers_active),"conductores")}${k("Documentos vencidos",fmt(d.expired),"vehículos/conductores")}${k("Mantenciones vencidas",fmt(m.overdue),"fecha/odómetro")}${k("Alertas abiertas",fmt(a.open),"sin resolver")}${k("Checklist",c.approved===null?"N/D":`${c.approved||0}/${(c.approved||0)+(c.pending||0)+(c.rejected||0)}`,"aprobados / con resultado")}</div><div class="grid two" style="margin-top:15px"><div class="card"><h3>Viajes por estado</h3>${Object.entries(o.trips_by_status||{}).map(([status,count])=>`<div class="operation-row"><span>${esc(status)}</span><b>${fmt(count)}</b></div>`).join("")||"<p>N/D</p>"}</div><div class="card"><h3>Alertas</h3><p>Abiertas: <b>${fmt(a.open)}</b></p><p>Resueltas: <b>${fmt(a.resolved)}</b></p><p>Críticas abiertas: <b>${fmt(a.open_critical)}</b></p></div></div>`}catch(err){A.innerHTML=`<div class="card"><h3>No se pudo cargar el dashboard ejecutivo</h3><p>${esc(err.message)}</p></div>`}};
async function renderKpiDashboard(filters={}){const params=new URLSearchParams();for(const key of ["from","to","client_id","truck_id","driver_id","status"]){if(filters[key])params.set(key,filters[key])}const [data,clients,trucks,drivers]=await Promise.all([get(`economics/kpis?${params}`),get("clients"),get("trucks"),get("drivers")]);const o=data.operations||{},e=data.economics||{},f=data.fleet||{},m=data.maintenance||{},d=data.documents||{},a=data.alerts||{},c=data.checklist||{},fmt=(v,fn=v=>Number(v).toLocaleString("es-CL"))=>v===null||v===undefined?"N/D":fn(v),select=(id,label,rows,value,key,text)=>`<div class="field"><label>${label}</label><select id="${id}"><option value="">Todos</option>${rows.map(x=>`<option value="${x[value]}" ${String(filters[key]||"")===String(x[value])?"selected":""}>${esc(x[text]||x[value])}</option>`).join("")}</select></div>`;A.innerHTML=`<div class="control-head"><div><div class="eyebrow">CONTROL ECONÓMICO Y OPERACIONAL</div><h2>Dashboard ejecutivo</h2><p>Indicadores bajo demanda. Delta/km utiliza distancia oficial planificada.</p></div></div><div class="card"><div class="formgrid"><div class="field"><label>Desde</label><input id="kpiFrom" type="date" value="${esc(filters.from||"")}"></div><div class="field"><label>Hasta</label><input id="kpiTo" type="date" value="${esc(filters.to||"")}"></div>${select("kpiClient","Cliente",clients,"id","client_id","name")}${select("kpiTruck","Camión",trucks,"id","truck_id","patente")}${select("kpiDriver","Conductor",drivers,"id","driver_id","name")}<div class="field"><label>Estado</label><select id="kpiStatus"><option value="">Todos</option>${["Planificado","Asignado","En carga","En tránsito","Detenido","Llegó a destino","Descargando","Completado","Cancelado"].map(x=>`<option ${filters.status===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="formactions"><button class="secondary" onclick="applyKpiFilters()">Aplicar filtros</button></div></div></div><div class="grid kpis" style="margin-top:15px">${k("Viajes completados",fmt(o.completed),"operación")}${k("Cumplimiento",fmt(o.compliance?.percentage,v=>`${Number(v).toLocaleString("es-CL",{maximumFractionDigits:1})}%`),`${o.compliance?.completed||0}/${o.compliance?.denominator??"N/D"} planificados`)}${k("Cargas",fmt(o.loads?.registered),`${o.loads?.delivered??"N/D"} entregadas`)}${k("Ingreso reconocido",fmt(e.recognized_revenue?.amount,money),`${e.recognized_revenue?.trips??0} viajes`)}${k("Costos directos",fmt(e.recognized_costs?.amount,money),`${e.recognized_costs?.trips??0} viajes`)}${k("Delta provisional",fmt(e.delta?.provisional,money),"no definitivo")}${k("Delta reconciliado",fmt(e.delta?.reconciled,money),"conciliado")}${k("Delta/km",fmt(e.delta_per_km?.provisional,money),"distancia oficial planificada")}</div><div class="grid kpis" style="margin-top:15px">${k("Missing data",fmt(e.delta?.missing_data_trips),"viajes")}${k("Camiones activos",fmt(f.active),"flota")}${k("En mantenimiento",fmt(f.maintenance),"camiones")}${k("Conductores activos",fmt(f.drivers_active),"conductores")}${k("Documentos vencidos",fmt(d.expired),"vehículos/conductores")}${k("Mantenciones vencidas",fmt(m.overdue),"fecha/odómetro")}${k("Alertas abiertas",fmt(a.open),"sin resolver")}${k("Checklist",c.approved===null?"N/D":`${c.approved||0}/${(c.approved||0)+(c.pending||0)+(c.rejected||0)}`,"aprobados / con resultado")}</div><div class="card" style="margin-top:15px"><h3>Viajes por estado</h3>${Object.entries(o.trips_by_status||{}).map(([status,count])=>`<div class="operation-row"><span>${esc(status)}</span><b>${fmt(count)}</b></div>`).join("")||"<p>N/D</p>"}</div>`}
window.applyKpiFilters=()=>renderKpiDashboard({from:document.getElementById("kpiFrom")?.value,to:document.getElementById("kpiTo")?.value,client_id:document.getElementById("kpiClient")?.value,truck_id:document.getElementById("kpiTruck")?.value,driver_id:document.getElementById("kpiDriver")?.value,status:document.getElementById("kpiStatus")?.value});
var esc=gpsEscape;const baseKpiDashboard=renderKpiDashboard;renderKpiDashboard=async function(filters={}){if(!document.querySelector("#nav button.active"))return;baseKpiDashboard(filters)};dashboard=()=>renderKpiDashboard(window.currentKpiFilters||{});
document.getElementById("x").onclick=close;document.getElementById("dx").onclick=()=>document.getElementById("drawer").classList.add("hidden");document.getElementById("newBtn").onclick=()=>openForm("trips");
setInterval(()=>{if(document.querySelector("#nav button.active")?.dataset.v==="dashboard")render("dashboard")},30000);
fetch("/api/health").then(r=>r.json()).then(x=>document.getElementById("health").textContent=x.ok?"● Base de datos conectada":"● Error DB").catch(()=>document.getElementById("health").textContent="● Servidor no disponible");render();
